export const COA_MAX_LEVEL = 5;
export const REPORT_LINE_LEVEL = 3;
export const BANK_HEADER = '1-1100';
export const CASH_HEADER = '1-1200';
const CATEGORY = { '1': 'Aset', '2': 'Liabilitas', '3': 'Ekuitas', '4': 'Pendapatan', '5': 'Beban' };
export const CODE_PATTERN = /^[1-5]-\d{4}(\.\d{2})?$/;
/** Level dari pola kode; null bila kode tidak sah. */
export function levelOfCode(code) {
    if (!CODE_PATTERN.test(code))
        return null;
    if (code.includes('.'))
        return /\.00$/.test(code) || /00$/.test(code.slice(0, 6)) ? null : 5;
    const d = code.slice(2);
    if (d === '0000')
        return 1;
    if (d.slice(1) === '000')
        return 2;
    if (d.slice(2) === '00')
        return 3;
    return 4;
}
/** Induk menurut pola kode (1-1101 → 1-1100 → 1-1000 → 1-0000). */
export function parentOfCode(code) {
    const lvl = levelOfCode(code);
    if (!lvl || lvl === 1)
        return null;
    if (lvl === 5)
        return code.slice(0, 6);
    const [c, d] = code.split('-');
    if (lvl === 4)
        return `${c}-${d.slice(0, 2)}00`;
    if (lvl === 3)
        return `${c}-${d.slice(0, 1)}000`;
    return `${c}-0000`;
}
export const categoryOfCode = (code) => CATEGORY[code[0]];
/** Aturan tipe per level: 1–3 selalu header, 5 selalu detail, 4 boleh keduanya. */
export function typeProblems(level, type) {
    if (level <= REPORT_LINE_LEVEL && type !== 'header')
        return `Akun level ${level} harus header — akun detail (transaksi) berada di level 4 atau 5.`;
    if (level === COA_MAX_LEVEL && type !== 'detail')
        return 'Akun level 5 harus detail.';
    if (level > COA_MAX_LEVEL)
        return `Kedalaman maksimum ${COA_MAX_LEVEL} level.`;
    return null;
}
