export function makeAccount(code, name, type, flags = {}) {
    const level = levelOfCode(code);
    return {
        code, name, type, category: categoryOfCode(code), parentCode: parentOfCode(code), level,
        normalSide: /^[15]/.test(code) ? 'debit' : 'credit',
        isIntercompany: Boolean(flags.interco), isContra: Boolean(flags.contra), isCash: Boolean(flags.cash), isComputed: Boolean(flags.computed), status: 'aktif',
    };
}
/** COA standar (tanpa akun rekening kas/bank, yang dibuat saat rekening didaftarkan). */
export const STANDARD_COA = [
    ...HEADERS.map(([c, n, f]) => makeAccount(c, n, 'header', f)),
    ...DETAILS.map(([c, n, f]) => makeAccount(c, n, 'detail', f)),
].sort((a, b) => a.code.localeCompare(b.code));
