export const LEGACY_CASH_ACCOUNT = '1-1100';
/** Rekening kas (nama bank "Kas") di bawah header Kas, lainnya di bawah header Bank. */
export const bankParentOf = (bankName) => (/^kas\b/i.test(bankName.trim()) ? CASH_HEADER : BANK_HEADER);
/** Alokasi kode akun detail per rekening, urut kode rekening — sama dengan trigger basis data. */
export function bankGlCodes(banks) {
    const next = {};
    const out = new Map();
    for (const b of [...banks].sort((x, y) => x.code.localeCompare(y.code))) {
        const parent = bankParentOf(b.bankName);
        next[parent] = (next[parent] ?? 0) + 1;
        out.set(b.code, `${parent.slice(0, 4)}${String(next[parent]).padStart(2, '0')}`);
    }
    return out;
}
