export const DEFAULT_ACCOUNT_LINKS = Object.fromEntries(ACCOUNT_LINK_DEFS.map((d) => [d.key, d.default]));
/** Validasi satu tautan: hanya akun detail aktif berkategori sesuai (header tidak boleh ditautkan). */
export function linkProblem(def, a) {
    if (!a)
        return `${def.label}: akun tidak ada di bagan akun.`;
    if (a.type !== 'detail')
        return `${def.label}: ${a.code} ${a.name} adalah header — hanya akun detail yang dapat ditautkan.`;
    if (a.status !== 'aktif')
        return `${def.label}: akun ${a.code} nonaktif.`;
    if (a.category !== def.category)
        return `${def.label}: harus akun kategori ${def.category}, bukan ${a.category}.`;
    if (a.isCash)
        return `${def.label}: akun kas/bank tidak dapat dipakai untuk pemetaan ini.`;
    if (def.key === 'currentEarnings' ? !a.isComputed : a.isComputed)
        return `${def.label}: ${def.key === 'currentEarnings' ? 'harus' : 'tidak boleh'} akun yang dihitung otomatis.`;
    return null;
}
